const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Define geometries and dates
    const longBeach = ee.Geometry.Point(-118.089042, 33.601421);
    const pismoBeach = ee.Geometry.Point(-120.727924, 35.128348);

    const targetDate = '2018-08-02';
    const targetWindow = 2; // days before/after for matching

    // 2. Function to mask low-quality SST pixels
    function maskSST(image) {
        const sst = image.select('sea_surface_temperature').multiply(0.01); // Convert to Kelvin
        const quality = image.select('Quality_level');
        // Mask low quality (0=bad, 1=acceptable, 2=good, 3=best)
        const mask = quality.gte(2).and(sst.gt(0)); // Valid SST > 0K
        return sst.updateMask(mask);
    }

    // 3. Get 2018 SST for target date ±window
    const targetStart = ee.Date(targetDate).advance(-targetWindow, 'day');
    const targetEnd = ee.Date(targetDate).advance(targetWindow, 'day');

    const sst2018 = ee.ImageCollection('MODIS/006/MOD28')
        .filterDate(targetStart, targetEnd)
        .filter(ee.Filter.calendarRange(2018, 2018, 'year'))
        .map(maskSST);

    // Check if 2018 data exists
    const sst2018Count = sst2018.size().getInfo();
    console.log(`2018 SST images: ${sst2018Count}`);

    if (sst2018Count === 0) {
        console.log("<answer>C1</answer>");
        return;
    }

    // 4. Get long-term average (2000-2017) for same seasonal window
    const longTermStart = ee.Date(targetDate).advance(-targetWindow, 'day');
    const longTermEnd = ee.Date(targetDate).advance(targetWindow, 'day');

    const longTermSST = ee.ImageCollection('MODIS/006/MOD28')
        .filterDate('2000-01-01', '2017-12-31')
        .filter(ee.Filter.dayOfYear(
            longTermStart.get('day_of_year'), 
            longTermEnd.get('day_of_year')
        ))
        .map(maskSST)
        .mean();

    // 5. Get 2018 composite (mean of available images in window)
    const sst2018Composite = sst2018.mean();

    // 6. Calculate anomalies at both points
    function getAnomaly(point, name) {
        // Get 2018 value
        const sst2018Val = sst2018Composite.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: point,
            scale: 1000,
            maxPixels: 1e9
        }).get('sea_surface_temperature');

        const sst2018CountPixels = sst2018Composite.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: point,
            scale: 1000,
            maxPixels: 1e9
        }).get('sea_surface_temperature');

        // Get long-term value
        const sstLongTermVal = longTermSST.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: point,
            scale: 1000,
            maxPixels: 1e9
        }).get('sea_surface_temperature');

        const sstLongTermCountPixels = longTermSST.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: point,
            scale: 1000,
            maxPixels: 1e9
        }).get('sea_surface_temperature');

        // Get values
        const sst2018 = sst2018Val.getInfo();
        const sstLongTerm = sstLongTermVal.getInfo();
        const count2018 = sst2018CountPixels.getInfo();
        const countLongTerm = sstLongTermCountPixels.getInfo();

        console.log(`${name} 2018 SST: ${sst2018 ? sst2018.toFixed(2) : 'N/A'} K (${count2018} pixels)`);
        console.log(`${name} Long-term SST: ${sstLongTerm ? sstLongTerm.toFixed(2) : 'N/A'} K (${countLongTerm} pixels)`);

        // Check for valid pixels
        if (count2018 === 0 || countLongTerm === 0) {
            console.log(`${name}: No valid pixels after masking`);
            return null;
        }

        // Calculate anomaly (2018 - long-term)
        const anomaly = sst2018 - sstLongTerm;
        console.log(`${name} Anomaly: ${anomaly.toFixed(2)} K`);
        return anomaly;
    }

    // 7. Get anomalies for both locations
    const anomalyLB = getAnomaly(longBeach, 'Long Beach');
    const anomalyPB = getAnomaly(pismoBeach, 'Pismo Beach');

    // 8. Validate and determine answer
    if (anomalyLB === null || anomalyPB === null) {
        console.log("<answer>C2</answer>");
        return;
    }

    if (isNaN(anomalyLB) || isNaN(anomalyPB) || 
        Math.abs(anomalyLB) > 20 || Math.abs(anomalyPB) > 20) { // Unreasonable SST anomaly
        console.log("<answer>C3</answer>");
        return;
    }

    // 9. Compare anomalies
    console.log(`Long Beach anomaly: ${anomalyLB.toFixed(2)} K`);
    console.log(`Pismo Beach anomaly: ${anomalyPB.toFixed(2)} K`);

    if (anomalyLB > anomalyPB) {
        console.log("<answer>A</answer>");
    } else {
        console.log("<answer>B</answer>");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE();
